package com.byawasaya.platform.plans;
import java.math.BigDecimal; import java.math.RoundingMode; import java.time.Instant; import java.util.*; import org.springframework.jdbc.core.JdbcTemplate; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import org.springframework.web.server.ResponseStatusException; import org.springframework.http.HttpStatus;
@Service public class PromotionService {
 private final JdbcTemplate jdbc; public PromotionService(JdbcTemplate jdbc){this.jdbc=jdbc;}
 public record AppliedPromo(UUID id,String code,BigDecimal discount){}
 public void validate(String code,String planCode){if(code==null||code.isBlank())return;String normalized=code.trim().toUpperCase(Locale.ROOT);List<Map<String,Object>> rows=jdbc.queryForList("SELECT code,discount_type,discount_value,starts_at,ends_at,max_redemptions,max_per_tenant,redeemed_count,eligible_plan_codes,active FROM promo_codes WHERE code=?",normalized);if(rows.isEmpty())throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Promo code is invalid.");Map<String,Object> p=rows.get(0);Instant now=Instant.now();if(!Boolean.TRUE.equals(p.get("active"))||toInstant(p.get("starts_at")).isAfter(now)||(p.get("ends_at")!=null&&!toInstant(p.get("ends_at")).isAfter(now)))throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Promo code is not active.");Object max=p.get("max_redemptions");if(max!=null&&((Number)p.get("redeemed_count")).longValue()>=((Number)max).longValue())throw new ResponseStatusException(HttpStatus.CONFLICT,"Promo code redemption limit reached.");String eligible=String.valueOf(p.get("eligible_plan_codes"));if(!eligible.contains("\""+planCode+"\"")&&!"[]".equals(eligible))throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Promo code does not apply to this plan.");}

 private Instant toInstant(Object v){if(v instanceof Instant i)return i;if(v instanceof java.time.OffsetDateTime o)return o.toInstant();if(v instanceof java.sql.Timestamp t)return t.toInstant();throw new IllegalStateException("Unsupported timestamp type.");}
 @Transactional public AppliedPromo redeem(String code,UUID businessId,String planCode,BigDecimal baseAmount,UUID subscriptionId){if(code==null||code.isBlank())return new AppliedPromo(null,null,BigDecimal.ZERO.setScale(2));String normalized=code.trim().toUpperCase(Locale.ROOT);List<Map<String,Object>> rows=jdbc.queryForList("SELECT id,code,discount_type,discount_value,starts_at,ends_at,max_redemptions,max_per_tenant,redeemed_count,eligible_plan_codes,active FROM promo_codes WHERE code=? FOR UPDATE",normalized);if(rows.isEmpty())throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Promo code is invalid.");Map<String,Object> p=rows.get(0);Instant now=Instant.now();if(!Boolean.TRUE.equals(p.get("active"))||toInstant(p.get("starts_at")).isAfter(now)||(p.get("ends_at")!=null&&!toInstant(p.get("ends_at")).isAfter(now)))throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Promo code is not active.");Object max=p.get("max_redemptions");if(max!=null&&((Number)p.get("redeemed_count")).intValue()>=((Number)max).intValue())throw new ResponseStatusException(HttpStatus.CONFLICT,"Promo code redemption limit reached.");Integer tenantLimit=(Integer)p.get("max_per_tenant");Long already=jdbc.queryForObject("SELECT COUNT(*) FROM promo_redemptions WHERE promo_code_id=? AND business_id=?",Long.class,p.get("id"),businessId);if(already!=null&&already>=tenantLimit)throw new ResponseStatusException(HttpStatus.CONFLICT,"This store has already used this promo code.");String eligible=String.valueOf(p.get("eligible_plan_codes"));if(!eligible.contains("\""+planCode+"\"")&&!"[]".equals(eligible))throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Promo code does not apply to this plan.");BigDecimal value=(BigDecimal)p.get("discount_value");BigDecimal discount="PERCENT".equals(p.get("discount_type"))?baseAmount.multiply(value).divide(new BigDecimal("100"),2,RoundingMode.HALF_UP):value.min(baseAmount);discount=discount.min(baseAmount).max(BigDecimal.ZERO).setScale(2,RoundingMode.HALF_UP);jdbc.update("UPDATE promo_codes SET redeemed_count=redeemed_count+1 WHERE id=?",p.get("id"));jdbc.update("INSERT INTO promo_redemptions(id,promo_code_id,business_id,subscription_id,discount_amount_npr) VALUES(gen_random_uuid(),?,?,?,?)",p.get("id"),businessId,subscriptionId,discount);return new AppliedPromo((UUID)p.get("id"),normalized,discount);}
}
